+// treeEntry is a single entry returned by the Git Trees API.
+type treeEntry struct {
+	Path string `json:"path"`
+	Type string `json:"type"` // "blob" or "tree"
+	SHA  string `json:"sha"`
+	Size int    `json:"size,omitempty"`
+}
+
+// gitTreeResponse is the response from the Git Trees API.
+type gitTreeResponse struct {
+	SHA       string      `json:"sha"`
+	Tree      []treeEntry `json:"tree"`
+	Truncated bool        `json:"truncated"`
+}
+
+// contentResponse is the response from the Contents API.
+type contentResponse struct {
+	Encoding string `json:"encoding"`
+	Content  string `json:"content"`
+	SHA      string `json:"sha"`
+}
+
+// commitResponse is used to extract commit SHA from a branch/ref query.
+type commitResponse struct {
+	Commit struct {
+		SHA string `json:"sha"`
+	} `json:"commit"`
+	SHA string `json:"sha"` // for tag and commit refs
+}
+
+// getTree fetches the full recursive file tree for a repo at the given ref.
+func (c *client) getTree(ctx context.Context, owner, repo, ref string) (*gitTreeResponse, error) {
+	// First get the commit SHA for the ref.
+	sha, err := c.getCommitSHA(ctx, owner, repo, ref)
+	if err != nil {
+		return nil, err
+	}
+
+	url := fmt.Sprintf("%s/repos/%s/%s/git/trees/%s?recursive=1", apiBase, owner, repo, sha)
+	body, err := c.do(ctx, url)
+	if err != nil {
+		return nil, err
+	}
+
+	var tree gitTreeResponse
+	if err := json.Unmarshal(body, &tree); err != nil {
+		return nil, domain.SourceError{
+			Code:      domain.ErrAdapterInternal,
+			Message:   "failed to parse git tree response: " + err.Error(),
+			Source:    domain.ErrorSourceAdapter,
+			Retryable: false,
+		}
+	}
+	return &tree, nil
+}
